package de.sebaro_ventures.design.designsystem

import androidx.compose.foundation.layout.Column
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import de.sebaro_ventures.design.SebaroTone

/**
 * The three appearance settings of every app as one value (D150): [mode] „Hell oder Dunkel“ (§12), [tone] „Farbton“
 * (§12.1), [reduceMotion] „Bewegung immer reduzieren“ (§12.2). The defaults follow the phone: System, the palette's base
 * tone, the app setting off (sbReduceMotion() still follows the system). The app stores [modeId], [toneId] and
 * [reduceMotion] under [KEY_MODE], [KEY_TONE] and [KEY_REDUCE_MOTION] and reads them back with [fromStored].
 */
data class SbAppearance(
    val mode: SbThemeMode = SbThemeMode.System,
    val tone: SebaroTone = SebaroTone.Cool,
    val reduceMotion: Boolean = false,
) {
    /** The stored word of [mode]: "system", "light" or "dark"; it never changes. */
    val modeId: String get() = mode.name.lowercase()

    /** The stored word of [tone]: "cool" or "warm" ([SebaroTone.id]); it never changes. */
    val toneId: String get() = tone.id

    companion object {
        /** The key of [modeId], a string; the web's localStorage key. */
        const val KEY_MODE = "sb-theme"

        /** The key of [toneId], a string; the web's localStorage key. */
        const val KEY_TONE = "sb-tone"

        /** The key of [reduceMotion], a boolean. */
        const val KEY_REDUCE_MOTION = "sb-reduce-motion"

        /**
         * The value from what the app stored: a missing or unknown value gives the default; case is ignored, so the
         * enum names a product stored before („Light“, „Warm“) read as well.
         */
        fun fromStored(mode: String?, tone: String?, reduceMotion: Boolean?): SbAppearance = SbAppearance(
            mode = SbThemeMode.entries.firstOrNull { it.name.equals(mode, ignoreCase = true) } ?: SbThemeMode.System,
            tone = SebaroTone.entries.firstOrNull { it.id.equals(tone, ignoreCase = true) } ?: SebaroTone.Cool,
            reduceMotion = reduceMotion ?: false,
        )
    }
}

/**
 * Einstellungen › „Darstellung“ (D150, spec/13 settings): „Hell oder Dunkel“ (§12), „Farbton“ (§12.1) and „Bewegung
 * immer reduzieren“ (§12.2) in this order, words from sbMessages(); each change calls [onChange] with [appearance]
 * changed in that one field. The group's heading stays with the screen (SbListHeader from the app's words).
 */
@Composable
fun SbAppearanceSettings(appearance: SbAppearance, onChange: (SbAppearance) -> Unit, modifier: Modifier = Modifier) {
    Column(modifier) {
        SbThemeChoice(appearance.mode, onChange = { onChange(appearance.copy(mode = it)) })
        SbToneChoice(appearance.tone, onChange = { onChange(appearance.copy(tone = it)) })
        SbMotionSetting(appearance.reduceMotion, onChange = { onChange(appearance.copy(reduceMotion = it)) })
    }
}
